  "source": "from __future__ import annotations

from pathlib import Path
import tempfile
from typing import Any

from core.capabilities.base import Capability, Skill, object_schema
from core.capabilities.registry import register
from core.capabilities.result import CapabilityResult

# Allowed third‑party SDK
from identityos import Identity


@register
class CreatorProbeCapability(Capability):
    id = "creator_probe"
    name = "Creator Probe"
    version = "1.0.0"
    author = "Daedalus"
    description = "Executes a small SDK probe: creates an identity, stores a memory and a goal, exports the identity, reloads it and verifies persistence."
    permissions = ["filesystem"]
    dependencies = ["identityos", "tempfile"]

    def install(self, identity_id: str, storage: Any) -> None:
        # No persistent installation state required for this probe
        pass

    def uninstall(self, identity_id: str, storage: Any) -> None:
        # Nothing to clean up – temporary directories are removed by the caller
        pass

    def prompts(self, identity_id: str) -> list[str]:
        return ["Use creator_probe.run to verify the Identity SDK behaviour."]

    def skills(self) -> list[Skill]:
        return [
            Skill(
                name="creator_probe.run",
                description="Create an identity, remember a memory, set a goal, export, reload and verify persistence.",
                input_schema=object_schema({"text": {"type": "string"}}, required=("text",)),
                verification_params={"text": "probe"},
            )
        ]

    def call(self, skill_name: str, **params: Any) -> CapabilityResult:
        if skill_name != "creator_probe.run":
            return CapabilityResult.fail(self.id, skill_name, "unknown_skill", "Skill not recognised")

        text: str = str(params.get("text", ""))
        if not text:
            return CapabilityResult.fail(self.id, skill_name, "invalid_input", "'text' parameter is required")

        # Create a persistent temporary directory for the duration of the probe
        temp_dir = tempfile.mkdtemp()
        try:
            # 1. Initialise the identity
            identity = Identity(identity_id="probe", name="CreatorProbe", storage_path=temp_dir)

            # 2. Store a memory and a goal using the public SDK
            identity.remember(text)
            identity.goal(text)

            # 3. Export the identity to a JSON file inside the temporary directory
            export_path = Path(temp_dir) / "identity.json"
            identity.export(export_path)

            # 4. Reload the identity from the same storage location
            loaded = Identity.load("probe", storage_path=temp_dir)

            # 5. Verify that the memory and goal persisted
            memories = loaded.memories()  # Expected: list[dict]
            goals = loaded.goals("all")   # Expected: list[dict]

            memory_persisted = any(text in str(m.values()) for m in memories)
            goal_persisted = any(text in str(g.values()) for g in goals)
            export_exists = export_path.is_file()

            result_data = {
                "text": text,
                "memory_persisted": memory_persisted,
                "goal_persisted": goal_persisted,
                "export_exists": export_exists,
            }

            # If any verification failed, report a failure; otherwise succeed
            if not (memory_persisted and goal_persisted and export_exists):
                return CapabilityResult.fail(
                    self.id,
                    skill_name,
                    "verification_failed",
                    f"Probe verification failed: {result_data}",
                    data=result_data,
                )

            return CapabilityResult.ok(self.id, skill_name, result_data, source="creator_probe")
        finally:
            # Clean up the temporary directory to avoid leaving stray files
            try:
                # Remove the directory tree safely – ignore errors if already removed
                import shutil
                shutil.rmtree(temp_dir, ignore_errors=True)
            except Exception:
                pass
